def get_adjacent_tuples(grid, row, col):
    """Return the 8 neighboring tuples around a cell, excluding the center."""
    adjacent = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            r, c = row + dr, col + dc
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
                adjacent.append(tuple(grid[r][c]))
    return adjacent


def get_coordinates(grid, *points):
    """Return coordinates of the given points in the grid."""
    coords = []
    for point in points:
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if tuple(value) == tuple(point):
                    coords.append((r, c))
    return coords


grid = [
    [[1, 2], [2, 3], [3, 4]],
    [[2, 5], [3, 4], [4, 3]],
    [[4, 3], [4, 5], [5, 6]],
]

print(get_adjacent_tuples(grid, 1, 1))
print(get_coordinates(grid, (3, 4), [2, 5], [3, 4], [4, 3], [4, 5]))
